import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"多级反馈队列","description":"","frontmatter":{"title":"多级反馈队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mlfq.md","filePath":"cs/mlfq.md","lastUpdated":1789023840000}'),_={name:"cs/mlfq.md"};function c(h,a,m,u,A,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="多级反馈队列" tabindex="-1">多级反馈队列 <a class="header-anchor" href="#多级反馈队列" aria-label="Permalink to &quot;多级反馈队列&quot;">​</a></h1><div class="epigraph"><p>多级反馈用任务自己的近期行为当估计：用完量子就降档、更大片；经常阻塞就留在高档、短片——不必事先知道作业长度。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Corbato 兼容时间共享系统的反馈调度整理</footer></div><p><a href="/cs/rr-quantum">上一课</a>的单队列 RR 对所有人同一 \\(q\\)，也做不到 SJF 那种「短者先」——因为不知道谁短。缺口是 <strong>MLFQ</strong>：若干 RR 队列，优先级从高到低，量子从短到长；任务用完本档量子则降入下一档，阻塞或等待过久可再升。本课钉这套反馈，不当成某内核源码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SJF 要预言；RR 不预言也不偏向短作业（除了 I/O 型用不完片）。MLFQ 把「刚才用尽量子」当成「可能是 CPU 型」的证据，把它放到更长量子、更低优先级的队列，让高档留给像交互那样短跑就睡的人。缺口不是再调一个全局 \\(q\\)，而是<strong>多条 runqueue 加迁移规则</strong>。</p><p><span class="marginnote">饥饿：CPU 型降到最低档后，若高档一直有交互，低档可能长期摸不到 CPU。对策是定期提升，或保证低档仍有 CPU 份额。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>队列 \\(Q_0,Q_1,\\ldots\\)：\\(Q_0\\) 先被选，其内 RR。用尽 \\(q_i\\) 降到 \\(Q_{i+1}\\)，\\(q_{i+1}\\gt q_i\\)。阻塞离开时记住档位，唤醒回原档或升档（实现各异）。调度：总是跑当前非空的最高档。本课不把具体 \\(q_i\\) 表当标准。</p>',8)),(e(),n(p,null,{default:r(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q0%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%20%E7%9F%AD%E9%87%8F%E5%AD%90%22%5D%20--%3E%20DOWN%5B%22%E7%94%A8%E5%B0%BD%E5%88%99%E9%99%8D%E6%A1%A3%22%5D%0A%20%20Q1%5B%22%E8%BE%83%E4%BD%8E%20%E8%BE%83%E9%95%BF%E9%87%8F%E5%AD%90%22%5D%20--%3E%20DOWN2%5B%22%E5%86%8D%E9%99%8D%22%5D%0A%20%20QN%5B%22%E6%9C%80%E4%BD%8E%E6%A1%A3%20%E9%95%BF%E9%87%8F%E5%AD%90%22%5D%20--%3E%20BOOST%5B%22%E5%AE%9A%E6%9C%9F%E6%8F%90%E5%8D%87%E9%98%B2%E9%A5%A5%E9%A5%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/cpu-vs-io-bound">CPU 型与 I/O 型</a>对齐：反馈就是在线分类。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MLFQ 用行为近似 SJF 且保持 RR 的响应：新任务或交互待在高档。规则必须防博弈：用户若每 \\(q-ε\\) 主动让出以假装 I/O 型，会占住高档——教材承认启发式可被骗。内核若用睡眠时间而不是「是否自愿 yield」来升档，骗术弱一些。本课不写攻防细节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 Linux CFS：CFS 用虚拟时间而不是固定多档量子。也不把 Solaris 旧 MLFQ 参数当定律。优先级反转还没锁：下一课才把「高优先级等低优先级持锁」请进来。</p><p>后课默认：分时可以用反馈分档。一旦有锁，静态或反馈的优先级都会反转，下一课讲优先级反转。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLFQ：多档 RR，用尽降档，近似短作业优先且不需预言。</li><li>须防低档饥饿与用户博弈。</li><li>锁引起的优先级反转是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Corbato et al. 时间共享系统。</li></ul>',8))])}const D=i(_,[["render",c]]);export{B as __pageData,D as default};
